using Microsoft.EntityFrameworkCore;
using RestaurantSystem.Application.Attendance;
using RestaurantSystem.Application.Catalog;
using RestaurantSystem.Application.Inventory;
using RestaurantSystem.Application.Operations;
using RestaurantSystem.Domain.Catalog;
using RestaurantSystem.Domain.Inventory;
using RestaurantSystem.Domain.Operations;

namespace RestaurantSystem.Infrastructure.Operations;
public sealed class OperationsService(ApplicationDbContext db, IInventoryWriter inventory, IBusinessClock clock) : IOperationsService
{
 public async Task<(CompositionDto? Value,string? Error)> ReplaceCompositionAsync(Guid id,IReadOnlyList<CompositionLineRequest> lines,string actor,CancellationToken ct=default) { if(lines is null||lines.Any(x=>x.ComponentProductId==Guid.Empty||x.ComponentProductId==id||x.QuantityPerOutputUnit<=0||x.UnitId==Guid.Empty)||lines.GroupBy(x=>x.ComponentProductId).Any(x=>x.Count()>1)) return(null,"INVALID_REQUEST"); await using var tx=await db.Database.BeginTransactionAsync(ct); var parent=await db.Products.SingleOrDefaultAsync(x=>x.Id==id,ct); if(parent is null)return(null,"NOT_FOUND"); if(!parent.IsActive||parent.ProductType!=ProductType.PREPARATION)return(null,"INVALID_COMPOSITION_PARENT"); var componentIds=lines.Select(x=>x.ComponentProductId).ToArray();var products=await db.Products.Include(x=>x.InventoryUnit).Where(x=>componentIds.Contains(x.Id)&&x.IsActive).ToDictionaryAsync(x=>x.Id,ct);var units=await db.Units.Where(x=>lines.Select(l=>l.UnitId).Contains(x.Id)&&x.IsActive).ToDictionaryAsync(x=>x.Id,ct);if(products.Count!=lines.Count||units.Count!=lines.Count||lines.Any(x=>units[x.UnitId].Dimension != products[x.ComponentProductId].InventoryUnit!.Dimension || units[x.UnitId].FactorToBase <= 0 || products[x.ComponentProductId].InventoryUnit!.FactorToBase <= 0))return(null,"INVALID_UNIT_CONVERSION"); db.ProductCompositions.RemoveRange(db.ProductCompositions.Where(x=>x.ParentProductId==id));db.ProductCompositions.AddRange(lines.Select(x=>new ProductComposition{ParentProductId=id,ComponentProductId=x.ComponentProductId,QuantityPerOutputUnit=x.QuantityPerOutputUnit,UnitId=x.UnitId,CreatedAt=clock.UtcNow,CreatedByUserId=actor}));await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return(await CompositionAsync(id,ct),null); }
 public async Task<CompositionDto?> CompositionAsync(Guid id,CancellationToken ct=default){var rows=await db.ProductCompositions.Where(x=>x.ParentProductId==id).ToArrayAsync(ct);var names=await db.Products.Where(x=>rows.Select(r=>r.ComponentProductId).Contains(x.Id)).ToDictionaryAsync(x=>x.Id,x=>x.Name,ct);return await db.Products.AnyAsync(x=>x.Id==id,ct)?new(id,rows.Select(x=>new CompositionLineDto(x.ComponentProductId,names[x.ComponentProductId],x.QuantityPerOutputUnit,x.UnitId)).ToArray()):null;}
 public async Task<(decimal? Value,string? Error)> SetMinimumStockAsync(Guid id,decimal? v,CancellationToken ct=default){if(v<0)return(null,"INVALID_REQUEST");var p=await db.Products.SingleOrDefaultAsync(x=>x.Id==id,ct);if(p is null)return(null,"NOT_FOUND");p.MinStock=v;await db.SaveChangesAsync(ct);return(v,null);}
 public async Task<(ProductionRequirementsDto? Value,string? Error)> RequirementsAsync(Guid id,decimal q,CancellationToken ct=default){if(q<=0)return(null,"INVALID_REQUEST");var target=await db.Products.Include(x=>x.InventoryUnit).SingleOrDefaultAsync(x=>x.Id==id&&x.IsActive,ct);if(target is null)return(null,"NOT_FOUND");var rows=await db.ProductCompositions.Where(x=>x.ParentProductId==id).ToArrayAsync(ct);if(rows.Length==0)return(null,"NO_USABLE_COMPOSITION");var ps=await db.Products.Include(x=>x.InventoryUnit).Where(x=>rows.Select(r=>r.ComponentProductId).Contains(x.Id)).ToDictionaryAsync(x=>x.Id,ct);var us=await db.Units.Where(x=>rows.Select(r=>r.UnitId).Contains(x.Id)).ToDictionaryAsync(x=>x.Id,ct);var balances=await db.InventoryBalances.Where(x=>ps.Keys.Contains(x.ProductId)).ToDictionaryAsync(x=>x.ProductId,x=>x.Quantity,ct);var items=rows.Select(r=>{var p=ps[r.ComponentProductId];var needed=Convert(r.QuantityPerOutputUnit*q,us[r.UnitId],p.InventoryUnit!);var current=balances.GetValueOrDefault(p.Id);return new ProductionRequirementDto(p.Id,p.Name,needed,current,Math.Max(0,needed-current),p.InventoryUnitId);}).ToArray();return(new(id,q,items,items.All(x=>x.ShortageQuantity==0)),null);}
 public async Task<(ProductionDto? Value,string? Error)> ProduceAsync(CreateProductionRequest r,string actor,CancellationToken ct=default){var req=await RequirementsAsync(r.ProductId,r.QuantityProduced,ct);if(req.Error is not null)return(null,req.Error);if(!req.Value!.HasSufficientStock)return(null,"PRODUCTION_STOCK_INSUFFICIENT");await using var tx=await db.Database.BeginTransactionAsync(ct);req=await RequirementsAsync(r.ProductId,r.QuantityProduced,ct);if(!req.Value!.HasSufficientStock)return(null,"PRODUCTION_STOCK_INSUFFICIENT");var production=new Production{ProductId=r.ProductId,QuantityProduced=r.QuantityProduced,Notes=r.Notes?.Trim(),ProducedAt=clock.UtcNow,CreatedByUserId=actor,ResponsibleEmployeeId=await db.Employees.Where(x=>x.UserId==actor&&x.IsActive).Select(x=>(Guid?)x.Id).SingleOrDefaultAsync(ct)};var cmds=req.Value.Components.Select(x=>new InventoryWriteCommand(x.ProductId,InventoryMovementType.PRODUCTION_CONSUMPTION,-x.RequiredQuantity,"Production",InventoryReferenceType.PRODUCTION,production.Id,actor)).Append(new InventoryWriteCommand(r.ProductId,InventoryMovementType.PRODUCTION_OUTPUT,r.QuantityProduced,"Production",InventoryReferenceType.PRODUCTION,production.Id,actor)).ToArray();var batch=await inventory.WriteBatchAsync(cmds,false,ct);if(batch.Error is not null)return(null,"PRODUCTION_STOCK_INSUFFICIENT");db.Productions.Add(production);db.ProductionConsumptions.AddRange(req.Value.Components.Select(x=>new ProductionConsumption{ProductionId=production.Id,ComponentProductId=x.ProductId,QuantityConsumed=x.RequiredQuantity}));await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return(new(production.Id,r.ProductId,r.QuantityProduced,production.ProducedAt,req.Value.Components),null);}
 public async Task<(ShiftContextDto? Value,string? Error)> OpenAsync(string actor,CancellationToken ct=default){await using var tx=await db.Database.BeginTransactionAsync(ct);var existing=await db.CashSessions.SingleOrDefaultAsync(x=>x.BusinessDate==clock.BusinessDate,ct);if(existing is not null)return(await CurrentShiftAsync(ct),null);var c=new CashSession{BusinessDate=clock.BusinessDate,OpenedAt=clock.UtcNow,OpenedByUserId=actor};c.Shifts.Add(new Shift{Type=ShiftType.MORNING,Status=ShiftStatus.ACTIVE,StartedAt=clock.UtcNow});c.Shifts.Add(new Shift{Type=ShiftType.NIGHT});db.CashSessions.Add(c);await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return(await CurrentShiftAsync(ct),null);}
 public async Task<ShiftContextDto?> CurrentShiftAsync(CancellationToken ct=default){var c=await db.CashSessions.Include(x=>x.Shifts).ThenInclude(x=>x.Assignments).SingleOrDefaultAsync(x=>x.BusinessDate==clock.BusinessDate&&x.IsOpen,ct);return c is null?null:new(c.Id,c.BusinessDate,c.Shifts.Select(x=>new ShiftDto(x.Id,x.Type,x.Status,x.Assignments.Select(a=>a.EmployeeId).ToArray())).ToArray());}
 public async Task<ShiftDto?> MyCurrentShiftAsync(string actor,CancellationToken ct=default){var employeeId=await db.Employees.Where(x=>x.UserId==actor&&x.IsActive).Select(x=>(Guid?)x.Id).SingleOrDefaultAsync(ct);if(employeeId is null)return null;var shift=await db.Shifts.Include(x=>x.Assignments).Where(x=>x.Status==ShiftStatus.ACTIVE&&x.Assignments.Any(a=>a.EmployeeId==employeeId)).SingleOrDefaultAsync(ct);return shift is null?null:new(shift.Id,shift.Type,shift.Status,shift.Assignments.Select(x=>x.EmployeeId).ToArray());}
 public async Task<(ShiftDto? Value,string? Error)> AssignAsync(Guid id,ShiftAssignmentRequest r,string actor,CancellationToken ct=default){if(r.EmployeeIds is null||r.EmployeeIds.Distinct().Count()!=r.EmployeeIds.Count)return(null,"INVALID_REQUEST");var s=await db.Shifts.Include(x=>x.Assignments).SingleOrDefaultAsync(x=>x.Id==id,ct);if(s is null)return(null,"NOT_FOUND");if(await db.Employees.CountAsync(x=>r.EmployeeIds.Contains(x.Id)&&x.IsActive,ct)!=r.EmployeeIds.Count)return(null,"INVALID_REQUEST");db.ShiftAssignments.RemoveRange(s.Assignments);db.ShiftAssignments.AddRange(r.EmployeeIds.Select(x=>new ShiftAssignment{ShiftId=id,EmployeeId=x,AssignedAt=clock.UtcNow,AssignedByUserId=actor}));await db.SaveChangesAsync(ct);return(new(id,s.Type,s.Status,r.EmployeeIds),null);}
 public async Task<(ShiftContextDto? Value,string? Error)> HandoverAsync(Guid id,HandoverRequest r,string actor,CancellationToken ct=default){await using var tx=await db.Database.BeginTransactionAsync(ct);var source=await db.Shifts.FromSqlInterpolated($"SELECT * FROM public.shifts WHERE \"Id\"={id} FOR UPDATE").SingleOrDefaultAsync(ct);if(source is null)return(null,"NOT_FOUND");var cashSession=await db.CashSessions.FromSqlInterpolated($"SELECT * FROM public.cash_sessions WHERE \"Id\"={source.CashSessionId} FOR UPDATE").SingleOrDefaultAsync(ct);if(cashSession is null||!cashSession.IsOpen)return(null,"INVALID_SHIFT_TRANSITION");var next=await db.Shifts.FromSqlInterpolated($"SELECT * FROM public.shifts WHERE \"CashSessionId\"={source.CashSessionId} AND \"Status\"='PENDING' FOR UPDATE").SingleOrDefaultAsync(ct);if(source.Status!=ShiftStatus.ACTIVE||next is null)return(null,"INVALID_SHIFT_TRANSITION");source.Status=ShiftStatus.COMPLETED;source.EndedAt=clock.UtcNow;source.HandoverNote=r.Note?.Trim();next.Status=ShiftStatus.ACTIVE;next.StartedAt=clock.UtcNow;await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return(await CurrentShiftAsync(ct),null);}
 public async Task<(SaleDto? Value,string? Error,IReadOnlyList<ProductionRequirementDto>? Shortages)> ConfirmSaleAsync(ConfirmSaleRequest r,string actor,CancellationToken ct=default){if(!Enum.IsDefined(r.SalesChannel)||!Enum.IsDefined(r.PaymentMethod)||(r.SalesChannel==SalesChannel.PEDIDOSYA)!=(r.PaymentMethod==PaymentMethod.EXTERNAL))return(null,"INVALID_REQUEST",null);await using var tx=await db.Database.BeginTransactionAsync(ct);var order=await db.Orders.FromSqlInterpolated($"SELECT * FROM public.orders WHERE id={r.OrderId} FOR UPDATE").Include(x=>x.Items).SingleOrDefaultAsync(ct);if(order is null)return(null,"NOT_FOUND",null);if(order.Status!=Domain.Orders.OrderStatus.ENTREGADO)return(null,"ORDER_NOT_DELIVERED",null);if(await db.Sales.AnyAsync(x=>x.OrderId==r.OrderId,ct))return(null,"SALE_ALREADY_CONFIRMED",null);var shift=await db.Shifts.FromSqlInterpolated($"SELECT * FROM public.shifts WHERE \"Status\"='ACTIVE' FOR UPDATE").SingleOrDefaultAsync(ct);if(shift is null)return(null,"NO_ACTIVE_SHIFT",null);var ids=order.Items.Select(x=>x.ProductId).ToArray();var ps=await db.Products.Where(x=>ids.Contains(x.Id)).ToDictionaryAsync(x=>x.Id,ct);var bal=await db.InventoryBalances.Where(x=>ids.Contains(x.ProductId)).ToDictionaryAsync(x=>x.ProductId,x=>x.Quantity,ct);var req=order.Items.GroupBy(x=>x.ProductId).Select(x=>new ProductionRequirementDto(x.Key,ps[x.Key].Name,x.Sum(y=>y.Quantity),bal.GetValueOrDefault(x.Key),Math.Max(0,x.Sum(y=>y.Quantity)-bal.GetValueOrDefault(x.Key)),ps[x.Key].InventoryUnitId)).Where(x=>x.ShortageQuantity>0).ToArray();if(req.Length>0&&!r.AcknowledgeStockShortage)return(null,"SALE_STOCK_CONFIRMATION_REQUIRED",req);var sale=new Sale{OrderId=r.OrderId,ShiftId=shift.Id,SalesChannel=r.SalesChannel,PaymentMethod=r.PaymentMethod,ConfirmedAt=clock.UtcNow,ConfirmedByUserId=actor,Subtotal=order.Items.Sum(x=>x.Quantity*x.UnitPrice),Total=order.Items.Sum(x=>x.Quantity*x.UnitPrice)};sale.Items.AddRange(order.Items.Select(x=>new SaleItem{OrderItemId=x.Id,ProductId=x.ProductId,Quantity=x.Quantity,UnitPrice=x.UnitPrice,LineTotal=x.Quantity*x.UnitPrice}));db.Sales.Add(sale);await db.SaveChangesAsync(ct);var batch=await inventory.WriteBatchAsync(order.Items.GroupBy(x=>x.ProductId).Select(x=>new InventoryWriteCommand(x.Key,InventoryMovementType.SALE,-x.Sum(y=>y.Quantity),"Sale",InventoryReferenceType.SALE,sale.Id,actor)).ToArray(),allowNegative:r.AcknowledgeStockShortage,ct);if(batch.Error is not null)return(null,"SALE_STOCK_CONFIRMATION_REQUIRED",req);await tx.CommitAsync(ct);return(new(sale.Id,sale.OrderId,sale.ShiftId,sale.Subtotal,sale.Total,sale.Items.Select(x=>new SaleItemDto(x.ProductId,x.Quantity,x.UnitPrice,x.LineTotal)).ToArray()),null,null);}
 public async Task<(PurchaseDto? Value,string? Error)> CreatePurchaseAsync(CreatePurchaseRequest r,string actor,IReadOnlySet<string> roles,CancellationToken ct=default){if(r.Lines is null||r.Lines.Count==0||r.Lines.Any(x=>x.Quantity<=0||x.UnitCost<0))return(null,"INVALID_REQUEST");var supplier=await db.Suppliers.SingleOrDefaultAsync(x=>x.Id==r.SupplierId&&x.IsActive,ct);if(supplier is null)return(null,"NOT_FOUND");var products=await db.Products.Include(x=>x.InventoryUnit).Where(x=>r.Lines.Select(l=>l.ProductId).Contains(x.Id)&&x.IsActive).ToDictionaryAsync(x=>x.Id,ct);var units=await db.Units.Where(x=>r.Lines.Select(l=>l.UnitId).Contains(x.Id)&&x.IsActive).ToDictionaryAsync(x=>x.Id,ct);if(products.Count!=r.Lines.Count||units.Count!=r.Lines.Count||r.Lines.Any(x=>units[x.UnitId].Dimension!=products[x.ProductId].InventoryUnit!.Dimension||units[x.UnitId].FactorToBase<=0||products[x.ProductId].InventoryUnit!.FactorToBase<=0))return(null,"INVALID_UNIT_CONVERSION");var kitchenOnly=roles.Contains("COCINA")&&!roles.Contains("ADMINISTRADOR")&&!roles.Contains("ENCARGADO");if(kitchenOnly&&(products.Values.Any(x=>x.ProductType!=ProductType.INGREDIENT)||string.IsNullOrWhiteSpace(r.ReceiptReference)))return(null,"PURCHASE_SCOPE_FORBIDDEN");var p=new Purchase{SupplierId=r.SupplierId,PurchaseDate=clock.BusinessDate,ReceiptReference=r.ReceiptReference?.Trim(),Notes=r.Notes?.Trim(),CreatedAt=clock.UtcNow,CreatedByUserId=actor};p.Items.AddRange(r.Lines.Select(x=>new PurchaseItem{ProductId=x.ProductId,Quantity=x.Quantity,UnitId=x.UnitId,UnitCost=x.UnitCost,LineTotal=x.Quantity*x.UnitCost}));p.Total=p.Items.Sum(x=>x.LineTotal);db.Purchases.Add(p);await db.SaveChangesAsync(ct);return(await PurchaseAsync(p.Id,ct),null);}
 public async Task<PurchaseDto?> PurchaseAsync(Guid id,CancellationToken ct=default){var p=await db.Purchases.Include(x=>x.Items).SingleOrDefaultAsync(x=>x.Id==id,ct);if(p is null)return null;var received=await db.PurchaseReceiptLines.Join(db.PurchaseReceipts,x=>x.PurchaseReceiptId,x=>x.Id,(l,r)=>new{l,r}).Where(x=>x.r.PurchaseId==id).ToDictionaryAsync(x=>x.l.PurchaseItemId,x=>x.l.ReceivedQuantity,ct);return new(p.Id,p.SupplierId,p.Status,p.Total,p.Items.Select(x=>new PurchaseLineDto(x.Id,x.ProductId,x.Quantity,x.UnitId,x.UnitCost,received.GetValueOrDefault(x.Id))).ToArray());}
 public async Task<PagedResponse<PurchaseDto>> PurchasesAsync(int page,int size,PurchaseStatus? status,CancellationToken ct=default){var q=db.Purchases.AsNoTracking();if(status is not null)q=q.Where(x=>x.Status==status);var total=await q.CountAsync(ct);var ids=await q.OrderByDescending(x=>x.CreatedAt).Skip((page-1)*size).Take(size).Select(x=>x.Id).ToArrayAsync(ct);return new((await Task.WhenAll(ids.Select(x=>PurchaseAsync(x,ct)))).Where(x=>x is not null).Cast<PurchaseDto>().ToArray(),page,size,total,(int)Math.Ceiling(total/(double)size));}
 public async Task<(PurchaseDto? Value,string? Error)> CancelPurchaseAsync(Guid id,CancelPurchaseRequest r,string actor,IReadOnlySet<string> roles,CancellationToken ct=default){if(string.IsNullOrWhiteSpace(r.Reason))return(null,"INVALID_REQUEST");await using var tx=await db.Database.BeginTransactionAsync(ct);var p=await db.Purchases.FromSqlInterpolated($"SELECT * FROM public.purchases WHERE \"Id\"={id} FOR UPDATE").Include(x=>x.Items).SingleOrDefaultAsync(ct);if(p is null)return(null,"NOT_FOUND");if(!await IsPurchaseScopeAllowedAsync(p.Items.Select(x=>x.ProductId),roles,ct))return(null,"PURCHASE_SCOPE_FORBIDDEN");if(p.Status!=PurchaseStatus.PENDIENTE)return(null,"PURCHASE_NOT_PENDING");p.Status=PurchaseStatus.CANCELADA;p.CancellationReason=r.Reason.Trim();p.CancelledAt=clock.UtcNow;p.CancelledByUserId=actor;await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return(await PurchaseAsync(id,ct),null);}
 public async Task<(PurchaseDto? Value,string? Error)> ReceivePurchaseAsync(Guid id,ReceivePurchaseRequest r,string actor,IReadOnlySet<string> roles,CancellationToken ct=default){await using var tx=await db.Database.BeginTransactionAsync(ct);var p=await db.Purchases.FromSqlInterpolated($"SELECT * FROM public.purchases WHERE \"Id\"={id} FOR UPDATE").Include(x=>x.Items).SingleOrDefaultAsync(ct);if(p is null)return(null,"NOT_FOUND");if(!await IsPurchaseScopeAllowedAsync(p.Items.Select(x=>x.ProductId),roles,ct))return(null,"PURCHASE_SCOPE_FORBIDDEN");if(p.Status!=PurchaseStatus.PENDIENTE)return(null,"PURCHASE_ALREADY_RECEIVED");if(r.Lines is null||r.Lines.Count!=p.Items.Count||r.Lines.Any(x=>x.ReceivedQuantity<=0)||r.Lines.Select(x=>x.PurchaseItemId).Distinct().Count()!=p.Items.Count||r.Lines.Any(x=>!p.Items.Any(i=>i.Id==x.PurchaseItemId)))return(null,"RECEIPT_INCOMPLETE");var receipt=new PurchaseReceipt{PurchaseId=id,ReceivedAt=clock.UtcNow,ReceivedByUserId=actor,Notes=r.Notes?.Trim()};receipt.Lines.AddRange(r.Lines.Select(x=>new PurchaseReceiptLine{PurchaseItemId=x.PurchaseItemId,ReceivedQuantity=x.ReceivedQuantity,UnitId=x.UnitId}));db.PurchaseReceipts.Add(receipt);await db.SaveChangesAsync(ct);var cmds=new List<InventoryWriteCommand>();foreach(var line in r.Lines){var item=p.Items.Single(x=>x.Id==line.PurchaseItemId);var product=await db.Products.Include(x=>x.InventoryUnit).SingleAsync(x=>x.Id==item.ProductId,ct);var unit=await db.Units.SingleAsync(x=>x.Id==line.UnitId,ct);if(unit.Dimension!=product.InventoryUnit!.Dimension||unit.FactorToBase<=0||product.InventoryUnit.FactorToBase<=0)return(null,"INVALID_UNIT_CONVERSION");cmds.Add(new(product.Id,InventoryMovementType.PURCHASE_RECEIPT,Convert(line.ReceivedQuantity,unit,product.InventoryUnit!),"Purchase receipt",InventoryReferenceType.PURCHASE,id,actor));}var batch=await inventory.WriteBatchAsync(cmds,true,ct);if(batch.Error is not null)return(null,batch.Error);p.Status=PurchaseStatus.RECIBIDA;await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return(await PurchaseAsync(id,ct),null);}
 private async Task<bool> IsPurchaseScopeAllowedAsync(IEnumerable<Guid> productIds,IReadOnlySet<string> roles,CancellationToken ct){if(roles.Contains("ADMINISTRADOR")||roles.Contains("ENCARGADO"))return true;if(!roles.Contains("COCINA"))return false;return !await db.Products.AnyAsync(x=>productIds.Contains(x.Id)&&x.ProductType!=ProductType.INGREDIENT,ct);} private async Task<bool> Compatible(Unit source,Guid target){var unit=await db.Units.FindAsync(target);return unit is not null&&source.Dimension==unit.Dimension&&source.FactorToBase>0&&unit.FactorToBase>0;} private static decimal Convert(decimal q,Unit from,Unit to)=>q*from.FactorToBase/to.FactorToBase;
}
